'use strict';
// Declarative catalog of everything OpenSweep can do. Adding a feature is usually
// just adding an entry here — the Windows backend executes these generically.
//
// Registry tweak value fields:
//   key   full hive path (HKEY_CURRENT_USER\..., HKEY_LOCAL_MACHINE\...)
//   name  value name
//   type  DWord | String | Binary
//   on    value written when the tweak is ON
//   off   value written when OFF; null = delete the value (restores Windows default)
// A tweak is "admin" if any value lives under HKEY_LOCAL_MACHINE.

const HKCU = 'HKEY_CURRENT_USER';
const HKLM = 'HKEY_LOCAL_MACHINE';
const ADV = `${HKCU}\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Advanced`;
const CDM = `${HKCU}\\Software\\Microsoft\\Windows\\CurrentVersion\\ContentDeliveryManager`;
const PERS = `${HKCU}\\Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize`;
const dw = (key, name, on, off = null) => ({ key, name, type: 'DWord', on, off });
const sz = (key, name, on, off = null) => ({ key, name, type: 'String', on, off });

